      "location": "Chart area",
      "fact": "A single blue line plot displays the data trend across the years 1880 to 1891."
    },
    {
      "location": "Left side of the chart (1880-1883)",
      "fact": "The line begins at a low vertical position (approx. 1,000) and fluctuates between the 1,000 and 1,600 marks."
    },
    {
      "location": "Middle of the chart (1884-1888)",
      "fact": "The line rises steadily from the 1,500 level to a plateau around the 2,300-2,400 level."
    },
    {
      "location": "Right side of the chart (1889-1891)",
      "fact": "The line reaches its highest vertical point (peak) in 1890, exceeding the 3,500 grid line, before dropping slightly in 1891."
    },
    {
      "location": "Overall trajectory",
      "fact": "The line shows a clear upward movement from the bottom-left region to the top-right region of the plot area."
    }
  ],
  "printed_facts": [
    {
      "location": "Top of the page",
      "fact": "The title reads: 'Decreasing Number of New Tourists in Town Z from 1880 to 1891'."
    },
    {
      "location": "Vertical axis (Y-axis)",
      "fact": "The axis is labeled 'Number of Tourists' with tick marks at 0, 500, 1,000, 1,500, 2,000, 2,500, 3,000, and 3,500."
    },
    {
      "location": "Horizontal axis (X-axis)",
      "fact": "The axis is labeled 'Year' with tick marks for each year from 1880 to 1891."
    }
  ],
  "public_definitions": [
    "Route to tourism growth planning",
    "Route to tourism decline response",
    "Keep on routine tourism monitoring"
  ],
